package com.ptms.controller; import com.ptms.dto.*; import com.ptms.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") public class DepartmentController{private final DepartmentService s;public DepartmentController(DepartmentService s){this.s=s;}@GetMapping public List<DepartmentDto>all(){return s.all();}@PostMapping public DepartmentDto save(@Valid @RequestBody DepartmentDto d){return s.save(d);}@PutMapping("/{id}") public DepartmentDto update(@PathVariable Long id,@Valid @RequestBody DepartmentDto d){return s.save(new DepartmentDto(id,d.name(),d.description(),d.enabled()));}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
